def handle_wikipedia_summary(params):
    topic = params.get("topic", "").strip()
    if not topic:
        return {"result": "❌ Please provide a valid topic.", "data": {}}

    url = f"https://en.wikipedia.org/api/rest_v1/page/summary/{topic}"
    result = {"result": "⚠️ Failed to fetch Wikipedia summary.", "data": {}}

    try:
        import requests
        response = requests.get(url, timeout=10)
        response.raise_for_status()
        data = response.json()

        if "extract" in data and "title" in data:
            summary = data["extract"]
            sentences = [s.strip() for s in summary.split(". ") if s.strip()]
            formatted_summary = ". ".join(sentences[:3]) + "."
            result["result"] = f"📖 **{data['title']}**\n{formatted_summary}"
            result["data"] = {
                "title": data["title"],
                "extract": data["extract"],
                "url": data.get("content_urls", {}).get("desktop", {}).get("page", "")
            }
        else:
            result["result"] = "❌ No summary found for the given topic."
    except Exception as e:
        result["result"] = f"⚠️ Wikipedia API error: {str(e)}"

    return result

