def handle_air_quality(params):
    city = params.get("city", "London")
    api_url = "https://air-quality-api.open-meteo.com/v1/air-quality"

    try:
        response = requests.get(api_url, params={"location": city})
        response.raise_for_status()
        data = response.json()

        if "results" not in data or not data["results"]:
            return {
                "result": f"⚠️ No air quality data found for {city}",
                "data": {"city": city, "error": "No results in API response"}
            }

        result = data["results"][0]
        pm25 = result.get("pm2_5", "N/A")
        aqi = result.get("aqi", "N/A")

        if pm25 == "N/A" or aqi == "N/A":
            return {
                "result": f"⚠️ Incomplete air quality data for {city}",
                "data": {"city": city, "pm2_5": pm25, "aqi": aqi}
            }

        aqi_level = (
            "Good" if aqi <= 50 else
            "Moderate" if aqi <= 100 else
            "Unhealthy for Sensitive Groups" if aqi <= 150 else
            "Unhealthy" if aqi <= 200 else
            "Very Unhealthy" if aqi <= 300 else
            "Hazardous"
        )

        result_str = (
            f"🌍 Air Quality in {city}\n"
            f"📊 AQI: {aqi} ({aqi_level})\n"
            f"💨 PM2.5: {pm25} µg/m³"
        )

        return {
            "result": result_str,
            "data": {
                "city": city,
                "aqi": aqi,
                "aqi_level": aqi_level,
                "pm2_5": pm25,
                "timestamp": datetime.datetime.now().isoformat()
            }
        }

    except requests.exceptions.RequestException as e:
        return {
            "result": f"⚠️ Could not fetch air quality data for {city}. API error: {str(e)}",
            "data": {"city": city, "error": str(e)}
        }
    except Exception as e:
        return {
            "result": f"⚠️ Unexpected error fetching air quality data for {city}.",
            "data": {"city": city, "error": str(e)}
        }



